-- ระบบซ้อมสัมภาษณ์: เพิ่มคำถามจากเอกสารคำถามสัมภาษณ์เข้ามหาวิทยาลัย (ม.6) เฉพาะข้อที่ยังไม่มีในระบบ
-- (ใช้กับฐานข้อมูลจริงแล้วเมื่อ 24 ต.ค. 2569) — ข้ามข้อที่ซ้ำ/คล้ายกับคำถามเดิมแล้ว
insert into public.iv_questions(category_id, question_text, guide_answer, difficulty, suggested_seconds, lang, is_active, is_ai)
select c.id, v.q, v.g, v.d, v.s, 'th', true, false
from (values
 ('คำถามทั่วไป','วิชาที่คุณชอบที่สุดคือวิชาอะไร เพราะอะไร','บอกวิชา เหตุผล ตัวอย่างที่เคยสนุกหรือทำได้ดี และเชื่อมกับสาขาที่เลือก','easy',90),
 ('คำถามทั่วไป','เคยเจอความล้มเหลวหรือปัญหาใหญ่ในชีวิตไหม แล้วรับมืออย่างไร','เล่าเรื่องจริง สิ่งที่ลงมือทำ ผลที่ได้ และสิ่งที่เรียนรู้','medium',150),
 ('คำถามทั่วไป','เล่าเรื่องหนึ่งเรื่องที่ทำให้คุณเข้าใจตัวเองมากขึ้น','เลือกเหตุการณ์จริง บอกว่าเห็นอะไรในตัวเองที่ไม่เคยรู้ และนำไปใช้อย่างไร','medium',150),
 ('คำถามทั่วไป','สาขานี้เรียนอะไรบ้าง ช่วยเล่าภาพรวมหลักสูตรเท่าที่คุณรู้','ดูโครงสร้างหลักสูตรจากเว็บไซต์คณะก่อนสอบ แล้วเล่าด้วยคำของตัวเอง ไม่ท่องตาม','medium',150),
 ('คำถามทั่วไป','มีรายวิชาหรือแนวทางของหลักสูตรที่คุณสนใจเป็นพิเศษไหม เพราะอะไร','เลือก 1–2 วิชาจากหลักสูตรจริง บอกเหตุผลและสิ่งที่อยากทำต่อ','medium',120),
 ('คำถามทั่วไป','เคยทำอะไรเพื่อลองดูว่าชอบสาขานี้จริง เช่น อ่านหนังสือ ทำโครงงาน เข้าค่าย หรือฝึกงาน','เล่าสิ่งที่ลองทำจริง ผลที่ได้ และเหตุผลที่ยังอยากเรียนต่อ','medium',150),
 ('คำถามทั่วไป','สาขานี้ต่างจากสาขาใกล้เคียงอย่างไร และทำไมจึงเลือกสาขานี้','เปรียบเทียบอย่างน้อย 1 สาขาใกล้เคียง แล้วบอกเหตุผลที่เลือกด้วยข้อมูลจริง','hard',180),
 ('คำถามทั่วไป','ถ้าเข้าเรียนแล้วพบว่าเนื้อหายากหรือไม่เหมือนที่คิด คุณจะทำอย่างไร','บอกแผนรับมือที่ทำได้จริง เช่น ถามอาจารย์ ตั้งกลุ่มติว ปรับวิธีเรียน พร้อมตัวอย่างที่เคยทำ','medium',150),
 ('คำถามทั่วไป','ทำไมคณะจึงควรรับคุณเข้าเรียน','สรุปจุดแข็ง 2–3 ข้อ พร้อมหลักฐานจากผลงานหรือประสบการณ์ ไม่เปรียบเทียบกับคนอื่น','hard',150),
 ('คำถามทั่วไป','อธิบายผลงานที่สำคัญที่สุดในแฟ้มสะสมผลงานของคุณ','เล่าเป้าหมาย สิ่งที่ทำ ผลลัพธ์ และสิ่งที่ภูมิใจ ภายใน 2–3 นาที','medium',180),
 ('คำถามทั่วไป','ผลงานชิ้นนี้คุณทำส่วนไหนด้วยตัวเอง','แยกให้ชัดว่าส่วนไหนเป็นของตนเอง ส่วนไหนทำเป็นทีม และตอบได้ถ้ากรรมการถามรายละเอียด','medium',120),
 ('คำถามทั่วไป','ทำไมคุณจึงเลือกทำโครงงานหรือกิจกรรมนี้','บอกที่มาของความสนใจและเหตุผลที่เลือก ไม่ใช่แค่ครูสั่ง','easy',120),
 ('คำถามทั่วไป','ระหว่างทำผลงาน เจอปัญหาอะไร และแก้อย่างไร','เล่าปัญหาจริง วิธีแก้ และสิ่งที่เรียนรู้ ยอมรับข้อผิดพลาดได้','medium',150),
 ('คำถามทั่วไป','ผลงานได้ผลตามเป้าหมายไหม มีหลักฐานหรือวิธีประเมินอย่างไร','บอกเป้าหมายตอนต้น เทียบกับผลจริง และหลักฐาน เช่น ตัวเลข ภาพ คำแนะนำจากผู้อื่น','hard',150),
 ('คำถามทั่วไป','ถ้ามีโอกาสทำผลงานนี้ใหม่ คุณจะปรับปรุงอะไร','ชี้จุดที่ทำได้ดีกว่าอย่างเฉพาะเจาะจง และเหตุผล','medium',120),
 ('คำถามทั่วไป','ผลงานหรือกิจกรรมนี้เกี่ยวข้องกับสาขาที่สมัครอย่างไร','โยงทักษะหรือความรู้จากผลงานไปยังสิ่งที่จะได้เรียนในสาขา','medium',120),
 ('คำถามทั่วไป','มีประเด็นหรือข่าวเกี่ยวกับสาขานี้ที่คุณสนใจไหม และคุณคิดเห็นอย่างไร','เลือกข่าวล่าสุดที่เชื่อถือได้ สรุปสั้น ๆ แล้วให้ความเห็นพร้อมเหตุผล','medium',150),
 ('คำถามทั่วไป','คนที่จะเรียนหรือทำงานในสายนี้ควรมีคุณสมบัติอะไร และคุณมีข้อไหนแล้ว','บอก 2–3 คุณสมบัติ พร้อมตัวอย่างที่แสดงว่าตนเองมี และข้อที่ยังต้องพัฒนา','medium',150),
 ('คำถามทั่วไป','อาชีพในสายนี้มีความท้าทายหรือข้อจำกัดอะไรบ้าง และคุณจะรับมืออย่างไร','แสดงว่ารู้ข้อเสียของอาชีพจริง ไม่มองแต่ด้านดี และบอกวิธีรับมือ','hard',150),
 ('คำถามทั่วไป','ถ้าใช้ความรู้ในสาขานี้แก้ปัญหาได้หนึ่งเรื่อง คุณจะเลือกเรื่องอะไร','เลือกปัญหาจริงที่ชัดเจน บอกว่าความรู้ของสาขาช่วยได้อย่างไร','medium',150),
 ('คำถามทั่วไป','อธิบายแนวคิดพื้นฐานหนึ่งข้อที่เกี่ยวข้องกับสาขาที่สมัครให้คนนอกวงการเข้าใจ','ใช้ภาษาง่าย ยกตัวอย่างใกล้ตัว ไม่ท่องศัพท์','hard',180),
 ('คำถามทั่วไป','ถ้าเจอสถานการณ์ที่หลักจริยธรรมสองข้อขัดกัน คุณจะตัดสินใจอย่างไร','บอกหลักคิดที่ใช้ชั่งน้ำหนัก ผลต่อผู้เกี่ยวข้อง และยอมรับว่าไม่มีคำตอบที่สมบูรณ์','hard',180),
 ('คำถามทั่วไป','ถ้าทำงานกลุ่มแล้วมีเพื่อนไม่ช่วยงาน คุณจะทำอย่างไร','เริ่มจากพูดคุยหาสาเหตุ แบ่งงานให้ชัด แล้วค่อยขอความช่วยเหลือจากครู ยกตัวอย่างจริง','medium',120),
 ('คำถามทั่วไป','ถ้าคะแนนสอบไม่ดี ทั้งที่ตั้งใจอ่านแล้ว คุณจะทำอย่างไร','วิเคราะห์สาเหตุ ปรับวิธีเรียน ขอคำแนะนำ และไม่ท้อ พร้อมตัวอย่างที่เคยทำ','medium',120),
 ('คำถามทั่วไป','คุณอยากนำความรู้ไปช่วยสังคมหรือชุมชนอย่างไร','เลือกเรื่องที่ทำได้จริง บอกขั้นตอนเริ่มต้น และโยงกับสาขาที่เรียน','medium',150),
 ('คำถามทั่วไป','ถ้าสมัครหลายที่ คุณใช้เกณฑ์อะไรตัดสินใจเลือก','ตอบอย่างตรงไปตรงมา บอกเกณฑ์ที่ชัด เช่น หลักสูตร ความถนัด ค่าใช้จ่าย โดยไม่ดูถูกที่อื่น','medium',120),
 ('คำถามทั่วไป','มีอะไรที่อยากให้กรรมการรู้เพิ่มเติม แต่ยังไม่ได้ถามไหม','เตรียมประเด็นสั้น ๆ 1 เรื่องที่ยังไม่ได้พูด เช่น จุดเด่นหรือความตั้งใจ','easy',90),
 ('แพทย์ · พยาบาล · สาธารณสุข','ถ้าผู้ป่วยกับญาติมีความเห็นต่างกันเรื่องการรักษา คุณจะรับมืออย่างไร','ฟังทุกฝ่าย ให้ข้อมูลที่ถูกต้อง เคารพการตัดสินใจของผู้ป่วย และปรึกษาทีม','hard',150),
 ('วิศวกรรม · วิทยาศาสตร์ · เทคโนโลยี','คุณสนใจปัญหาทางเทคนิคเรื่องอะไรเป็นพิเศษ เพราะอะไร','เลือกปัญหาที่ชัด อธิบายว่าทำไมน่าสนใจ และเคยลองหาคำตอบอย่างไร','medium',150),
 ('วิศวกรรม · วิทยาศาสตร์ · เทคโนโลยี','เคยทดลอง เขียนโปรแกรม หรือวิเคราะห์ข้อมูลอะไรมาบ้าง อธิบายวิธีคิดและข้อผิดพลาดที่พบ','เล่าขั้นตอน เหตุผลของวิธีที่เลือก ข้อผิดพลาดจริง และวิธีแก้','hard',180),
 ('บริหาร · บัญชี · เศรษฐศาสตร์','คุณสนใจธุรกิจหรือปัญหาเศรษฐกิจเรื่องอะไรเป็นพิเศษ','เลือกเรื่องที่ติดตามจริง บอกสิ่งที่รู้ และความเห็นพร้อมเหตุผล','medium',150),
 ('บริหาร · บัญชี · เศรษฐศาสตร์','ถ้ามีงบประมาณจำกัด คุณจะจัดลำดับการใช้เงินอย่างไร','บอกเกณฑ์จัดลำดับ เช่น จำเป็น/คุ้มค่า/เร่งด่วน พร้อมตัวอย่างตัวเลขง่าย ๆ','medium',150),
 ('มนุษยศาสตร์ · สังคม · นิติ · รัฐศาสตร์','ประเด็นสังคมเรื่องหนึ่งที่คุณสนใจ มีเหตุผลสนับสนุนและข้อโต้แย้งอะไรบ้าง','นำเสนอทั้งสองมุมอย่างเป็นธรรมก่อน แล้วค่อยบอกความเห็นของตนเองพร้อมเหตุผล','hard',180),
 ('มนุษยศาสตร์ · สังคม · นิติ · รัฐศาสตร์','ทำไมคุณจึงสนใจภาษาหรือวัฒนธรรมที่เลือกเรียน','เล่าที่มาของความสนใจ ประสบการณ์ที่ใช้ภาษา/สัมผัสวัฒนธรรมนั้น และเป้าหมายต่อไป','easy',120)
) v(cat,q,g,d,s)
join public.iv_categories c on c.name = v.cat
where not exists (select 1 from public.iv_questions x where x.category_id=c.id and x.question_text=v.q);
